pub use bevy_reflect2_macros::type_path;
use core::{
    fmt::{Debug, Display},
    ops::Deref,
};

/// A standardized, stable Rust type path, intended to be usable as a "canonical" name for a type.
///
/// The engine uses this over [`core::any::type_name`] for stability and flexibility.
///
/// This is automatically generated by the `#[derive(Reflect)]` macro
/// and allows type path information to be processed without an instance of that type.
///
/// This is intended to be constructed by derives and proc macros in this crate, as populating the
/// ranges for each part of the path can be challenging.
///
/// This uses a condensed representation to avoid storing multiple strings in the output binary.
pub struct TypePath {
    full: &'static str,
    short: &'static str,
    type_ident: (usize, usize),
    crate_name: Option<(usize, usize)>,
    module_name: Option<(usize, usize)>,
}

impl Debug for TypePath {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str(self.full)
    }
}

impl Display for TypePath {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str(self.short)
    }
}

impl Deref for TypePath {
    type Target = str;

    fn deref(&self) -> &Self::Target {
        self.full
    }
}
impl TypePath {
    pub const fn new(
        full: &'static str,
        short: &'static str,
        type_ident: (usize, usize),
        crate_name: Option<(usize, usize)>,
        module_name: Option<(usize, usize)>,
    ) -> Self {
        Self {
            full,
            short,
            type_ident,
            crate_name,
            module_name,
        }
    }

    pub const fn full(&self) -> &'static str {
        self.full
    }

    pub const fn short(&self) -> &'static str {
        self.short
    }

    pub const fn type_ident(&self) -> &'static str {
        const_index(self.short, self.type_ident)
    }

    pub const fn crate_name(&self) -> Option<&'static str> {
        match self.crate_name {
            Some(v) => Some(const_index(self.full, v)),
            None => None,
        }
    }

    pub const fn module_name(&self) -> Option<&'static str> {
        match self.module_name {
            Some(v) => Some(const_index(self.full, v)),
            None => None,
        }
    }
}

const fn const_index(s: &str, range: (usize, usize)) -> &str {
    s.split_at(range.0).1.split_at(range.1 - range.0).0
}

pub const fn find_ascii_char(s: &str, delimiter: u8) -> Option<usize> {
    let bytes = s.as_bytes();
    let mut i = 0;

    while i < bytes.len() {
        if bytes[i] == delimiter {
            return Some(i);
        }
        i += 1;
    }
    None
}

#[cfg(test)]
mod test {
    use crate as bevy_reflect2;
    use crate::type_path;

    #[test]
    fn type_path_macro() {
        let path = type_path!(f32);
        assert_eq!(path.full(), "f32");
        assert_eq!(path.short(), "f32");
        assert_eq!(path.type_ident(), "f32");
        assert_eq!(path.crate_name(), None);
        assert_eq!(path.module_name(), None);

        let path = type_path!(core::f32);
        assert_eq!(path.full(), "core::f32");
        assert_eq!(path.short(), "f32");
        assert_eq!(path.type_ident(), "f32");
        assert_eq!(path.crate_name(), Some("core"));
        assert_eq!(path.module_name(), Some("core"));

        let path = type_path!(core::float::f32);
        assert_eq!(path.full(), "core::float::f32");
        assert_eq!(path.short(), "f32");
        assert_eq!(path.type_ident(), "f32");
        assert_eq!(path.crate_name(), Some("core"));
        assert_eq!(path.module_name(), Some("core::float"));

        // #[derive(Reflect)]
        // struct Foo {
        //     value: u32,
        // }

        // let path = type_path!(Vec<Foo>);
        // assert_eq!(path.full(), "Vec<f32>");
        // assert_eq!(path.short(), "Vec<f32>");
        // assert_eq!(path.type_ident(), "Vec");
        // assert_eq!(path.crate_name(), None);
        // assert_eq!(path.module_name(), None);
    }
}
